23	func (s *APIV1Service) convertMemoFromStore(ctx context.Context, memo *store.Memo, reactions []*store.Reaction, attachments []*store.Attachment, relations []*v1pb.MemoRelation) (*v1pb.Memo, error) {
24		creatorMap, err := s.listUsersByID(ctx, []int32{memo.CreatorID})
25		if err != nil {
26			return nil, errors.Wrap(err, "failed to list memo creators")
27		}
28		return s.convertMemoFromStoreWithCreators(ctx, memo, reactions, attachments, relations, creatorMap)
